INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, episode_type, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs, alignment_method, alignment_coverage, status, published_at) VALUES ('california-high-speed-rail-and-the-billionaire-tax', 'ask-eve:2026-10-24_california-high-speed-rail-and-the-billionaire-tax', '2026-10-24', 'California High-Speed Rail & the Billionaire Tax', 1, 'en', NULL, '2026-10-24T07:47:19.000Z', '2026-10-24T08:43:28.000Z', 98, 'episodes/2026-10-24_california-high-speed-rail-and-the-billionaire-tax.md', '78761f8bcf522eb9ad6aec99c41181772b8f25ed7a88d5793d61c0344f0acebd', 70073, 'Recorded on Saturday morning, October 24, 2026 (07:47–08:43 UTC), this session opens with a brief two-minute live bootstrap where David loads Eve''s master context pack (`context.txt`), then dives into two major California policy battles. First (turns 13–78, 07:49–08:23 UTC, published standalone as Episode 10): California High-Speed Rail—how 2008''s $10B Prop 1A bond promise became $15.5B spent and a $126B+ estimate with zero track laid, the $677M / 130,000-page CEQA industry funded by the same engineering firms that backed the ballot measure, CEO Ian Choudri''s KPMG travel scandal and $537.3M Change Order 427, Governor Gavin Newsom''s veto of the Inspector General staffing bill, Texas vs. Spain vs. China, and Eve drafting a $50M ballot initiative to redirect the $1B/year cap-and-trade siphon. Second (turns 79–98, 08:24–08:43 UTC, published standalone as Episode 11): Proposition 40, California''s one-time 5% billionaire wealth tax—SEIU-UHW president Dave Regan''s 48-initiative leverage machine, UC Berkeley economists Emmanuel Saez and Gabriel Zucman''s precedent play, Section 5033(c)(3)(C)''s voting-control valuation trap for private startup founders, the California Supreme Court fast-lane challenge, and how wealth taxes actually work in Norway, Switzerland, Spain, and France.', 'full', 2, 'xai_tts voice=eve', 'tts-reconstructed', 'elevenlabs_tts voice=oIYMwdEzgKSOV3gVsAjB model=eleven_v4', 1, 'AI-reconstructed audio: the voices in this episode were generated from the verbatim text transcript (Eve with xAI text-to-speech in the ''eve'' voice, David''s lines with his ElevenLabs AI voice clone). No original audio was used.', 'audio/en/2026-10-24_california-high-speed-rail-and-the-billionaire-tax.v1.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-24_california-high-speed-rail-and-the-billionaire-tax.v1.mp3', 61641470, 'bb4f9e4a282c00f49acf2b80ed654b781b5949c3636fae5986becc0fe6b3ab13', 'audio/mpeg', 3852, -16.8, 'tts-exact', 1.0, 'published', '2026-10-24T09:00:00Z')
